/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fixture` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `sample_key` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '稳定导入标识：official-2026-* / demo-*',
  `tournament_id` int unsigned NOT NULL COMMENT 'FK -> tournament.id',
  `venue_id` int unsigned NOT NULL COMMENT 'FK -> venue.id',
  `home_team_id` int unsigned NOT NULL COMMENT 'FK -> national_team.id',
  `away_team_id` int unsigned NOT NULL COMMENT 'FK -> national_team.id，不得等于主队',
  `stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'group' COMMENT '本期仅 group',
  `group_name` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '如 A，演示可空',
  `kickoff_at` datetime NOT NULL COMMENT 'UTC 开球时间，秒精度',
  `match_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scheduled' COMMENT 'scheduled / finished',
  `publication_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft / published',
  `home_score` smallint unsigned DEFAULT NULL COMMENT '0-99，未开赛为 NULL',
  `away_score` smallint unsigned DEFAULT NULL COMMENT '0-99，未开赛为 NULL',
  `is_demo` smallint unsigned NOT NULL DEFAULT '1' COMMENT '0 / 1，新建默认演示',
  `source_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '正式样本必填 FIFA 来源，演示为空',
  `source_checked_at` datetime DEFAULT NULL COMMENT '正式样本核对时间，UTC',
  `published_at` datetime DEFAULT NULL COMMENT '首次发布 UTC 时间，草稿为空',
  `score_updated_at` datetime DEFAULT NULL COMMENT '完赛比分录入/变更时间，未开赛为空',
  `created_at` datetime NOT NULL COMMENT 'UTC',
  `updated_at` datetime NOT NULL COMMENT 'UTC',
  `home_source` varchar(87) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `away_source` varchar(87) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `winner_side` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decided_by` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `home_penalties` smallint unsigned DEFAULT NULL,
  `away_penalties` smallint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fixture_sample_key` (`sample_key`),
  KEY `idx_fixture_public_status_time` (`publication_status`,`match_status`,`kickoff_at`,`id`),
  KEY `idx_fixture_result_update` (`publication_status`,`match_status`,`score_updated_at`,`id`),
  KEY `idx_fixture_tournament` (`tournament_id`),
  KEY `idx_fixture_venue` (`venue_id`),
  KEY `idx_fixture_home` (`home_team_id`),
  KEY `idx_fixture_away` (`away_team_id`),
  CONSTRAINT `fk_fixture_away_team` FOREIGN KEY (`away_team_id`) REFERENCES `national_team` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_fixture_home_team` FOREIGN KEY (`home_team_id`) REFERENCES `national_team` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_fixture_tournament` FOREIGN KEY (`tournament_id`) REFERENCES `tournament` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_fixture_venue` FOREIGN KEY (`venue_id`) REFERENCES `venue` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_fixture_is_demo` CHECK ((`is_demo` in (0,1))),
  CONSTRAINT `chk_fixture_match_status` CHECK ((`match_status` in (_utf8mb4'scheduled',_utf8mb4'finished'))),
  CONSTRAINT `chk_fixture_publication_status` CHECK ((`publication_status` in (_utf8mb4'draft',_utf8mb4'published'))),
  CONSTRAINT `chk_fixture_published_at` CHECK ((((`publication_status` = _utf8mb4'draft') and (`published_at` is null)) or ((`publication_status` = _utf8mb4'published') and (`published_at` is not null)))),
  CONSTRAINT `chk_fixture_score_pair` CHECK ((((`home_score` is null) and (`away_score` is null)) or ((`home_score` between 0 and 99) and (`away_score` between 0 and 99)))),
  CONSTRAINT `chk_fixture_source` CHECK (((`is_demo` = 1) or ((`is_demo` = 0) and (`source_url` is not null) and (`source_checked_at` is not null)))),
  CONSTRAINT `chk_fixture_status_score` CHECK ((((`match_status` = _utf8mb4'scheduled') and (`home_score` is null) and (`away_score` is null) and (`score_updated_at` is null)) or ((`match_status` = _utf8mb4'finished') and (`home_score` is not null) and (`away_score` is not null) and (`score_updated_at` is not null)))),
  CONSTRAINT `chk_fixture_teams_differ` CHECK ((`home_team_id` <> `away_team_id`))
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

