  CONSTRAINT `fk_guest_review_message` FOREIGN KEY (`message_id`) REFERENCES `guest_message` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_guest_review_reviewer` FOREIGN KEY (`reviewer_id`) REFERENCES `account` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_guest_review_decision` CHECK ((`decision` in (_utf8mb4'approved',_utf8mb4'rejected')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
