INSERT INTO `project_member` VALUES (1,1,'成员一','工程与站点整合','搭建运行基线，让独立功能成为一个完整的网站。',10,'2026-11-21 08:29:47','2026-11-21 08:29:47','member-1'),(2,1,'成员二','团队展示与数据设计','组织团队资料与数据关系，让每一份贡献有迹可循。',20,'2026-11-21 08:29:47','2026-11-21 08:29:47','member-2'),(3,1,'成员三','赛事浏览与赛果发布','把赛程、比分与比赛故事，变成清楚可查的信息。',30,'2026-11-21 08:29:47','2026-11-21 08:29:47','member-3'),(4,1,'成员四','视觉与球迷互动','确定页面与赛事素材，让球迷的声音进入网站。',40,'2026-11-21 08:29:47','2026-11-21 08:29:47','member-4');
